protocol Formatter {
    func format(value: Int) -> String
}

extension Formatter {
    func format(value: Int) -> String {
        return "Value: \(value)"
    }
}

struct CustomFormatter: Formatter {}

let fmt: Formatter = CustomFormatter()
print(fmt.format(value: 42))

protocol Named {
    var name: String { get }
}
protocol Aged {
    var age: Int { get }
}

struct Person: Named, Aged {
    let name: String
    let age: Int
}

func display(entity: Named & Aged) {
    print("\(entity.name) is \(entity.age)")
}

let person = Person(name: "Taylor", age: 30)
display(entity: person)

protocol Scoreable {
    var score: Int { get }
    var isPassing: Bool { get }
}

extension Scoreable {
    var isPassing: Bool {
        return score >= 70
    }
}

struct ExamResult: Scoreable {
    let score: Int
}

let result = ExamResult(score: 85)
print(result.isPassing)

