print(dev.takeBreak())

protocol IdentifiableEntity {
    var id: String { get }
}

extension Collection where Element: IdentifiableEntity {
    func allIDs() -> [String] {
        return self.map { $0.id }
    }
}

struct UserItem: IdentifiableEntity {
    let id: String
}

let items = [UserItem(id: "u1"), UserItem(id: "u2")]
print(items.allIDs().joined(separator: ", "))

